import React, { useState } from 'react';
import ProjectModal from '../ProjectModal/ProjectModal';
import './Portfolio.css';

const Portfolio = () => {
    const [selectedProject, setSelectedProject] = useState(null);
    const [showModal, setShowModal] = useState(false);

    const projects = [
        {
            id: 1,
            title: "GERENCIAMENTO DE PROJETOS",
            category: "Node.js",
            date: "2025",
            status: "Completo",
            description: "É uma aplicação local (executada em localhost) disponível em duas versões: uma desenvolvida em PHP e outra em React. Ambas as versões permitem aos usuários gerenciar projetos de forma eficiente, oferecendo funcionalidades para abrir, editar e excluir projetos.",
            technologies: ["React", "Node.js", "PHP", "MySQL"],
            images: [
                "/assets/img/portfolio/thumbnail/Localhost.png",
                "/assets/img/portfolio/thumbnail/PROJETO-CRUD.png"
            ],
            githubUrl: "https://github.com/nagybhe"
        },
        {
            id: 2,
            title: "INTERFACE MOBILE",
            category: "React Native",
            date: "2024",
            status: "Completo",
            description: "Aplicativo mobile desenvolvido em React Native com interface moderna e responsiva.",
            technologies: ["React Native", "JavaScript", "Firebase"],
            images: [
                "/assets/img/portfolio/thumbnail/INTERFACE-MOBILE.png"
            ]
        },
        // Adicione os outros projetos aqui...
    ];

    const handleProjectClick = (project) => {
        setSelectedProject(project);
        setShowModal(true);
    };

    const handleCloseModal = () => {
        setShowModal(false);
        setSelectedProject(null);
    };

    return (
        <section id="portfolio" className="portfolio section-bg">
            <div className="container">
                <div className="section-title">
                    <h2>Projetos</h2>
                </div>

                <div className="row portfolio-container">
                    {projects.map(project => (
                        <div key={project.id} className="col-lg-4 col-md-6 portfolio-item">
                            <div className="portfolio-wrap" onClick={() => handleProjectClick(project)}>
                                <img
                                    src={project.images[0]}
                                    className="img-fluid"
                                    alt={project.title}
                                />
                                <div className="portfolio-links">
                                    <a href={project.images[0]} data-gallery="portfolioGallery">
                                        <i className="bx bx-plus"></i>
                                    </a>
                                    <a href="#" title="Mais Detalhes">
                                        <i className="bx bx-link"></i>
                                    </a>
                                </div>
                            </div>
                            <div className="portfolio-info">
                                <h4>{project.title}</h4>
                                <p>{project.category}</p>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Modal */}
                <ProjectModal
                    show={showModal}
                    handleClose={handleCloseModal}
                    project={selectedProject}
                />
            </div>
        </section>
    );
};

export default Portfolio;
